"use client";

import { Download, Loader2 } from "lucide-react";
import type { ReactNode } from "react";

import { Button } from "@/components/ui/button";
import { useDownload } from "@/hooks/useDownload";
import type { QueryParams } from "@/lib/api-client";

/** Authenticated PDF/CSV download (the file is generated by the API on request, nothing is stored). */
export function DownloadButton({
  path, filename, query, children, variant = "outline", size = "sm", disabled,
}: {
  path: string;
  filename: string;
  query?: QueryParams;
  children: ReactNode;
  variant?: "outline" | "default" | "ghost";
  size?: "sm" | "default";
  disabled?: boolean;
}) {
  const { download, isDownloading, error } = useDownload();
  return (
    <span className="inline-flex flex-col items-start gap-1">
      <Button variant={variant} size={size} disabled={disabled || isDownloading} onClick={() => void download(path, filename, query)}>
        {isDownloading ? <Loader2 className="size-4 animate-spin" /> : <Download className="size-4" />} {children}
      </Button>
      {error ? <span role="alert" className="max-w-56 text-xs text-destructive">{error}</span> : null}
    </span>
  );
}
